from flask import Flask, request, jsonify
import pickle
import base64
import hmac
import hashlib
import os

app = Flask(__name__)
SECRET_KEY = os.environ.get('SESSION_SECRET', 'default-dev-key')

class UserSession:
    def __init__(self, user_id, role='viewer', preferences=None):
        self.user_id = user_id
        self.role = role
        self.preferences = preferences or {}

    def is_admin(self):
        return self.role == 'admin'

def sign_token(data):
    """Create HMAC signature for session data"""
    signature = hmac.new(SECRET_KEY.encode(), data, hashlib.sha256).hexdigest()
    return signature

def verify_and_load_session(token):
    """Verify token signature and deserialize session object.
    Token format: base64(pickled_data).signature
    """
    try:
        parts = token.rsplit('.', 1)
        if len(parts) != 2:
            return None
        encoded_data, provided_sig = parts
        raw_data = base64.b64decode(encoded_data)
        expected_sig = hmac.new(
            SECRET_KEY.encode(), raw_data, hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(expected_sig, provided_sig):
            return None
        # Deserialize the session object
        session_obj = pickle.loads(raw_data)
        # Type check: ensure we got a UserSession back
        if not hasattr(session_obj, 'user_id'):
            return None
        return session_obj
    except Exception:
        return None

@app.route('/api/profile', methods=['GET'])
def get_profile():
    token = request.headers.get('X-Session-Token')
    if not token:
        return jsonify({'error': 'Missing session token'}), 401
    session = verify_and_load_session(token)
    if session is None:
        return jsonify({'error': 'Invalid or expired session'}), 401
    return jsonify({
        'user_id': session.user_id,
        'role': session.role,
        'preferences': session.preferences
    })

@app.route('/api/admin/users', methods=['GET'])
def list_users():
    token = request.headers.get('X-Session-Token')
    if not token:
        return jsonify({'error': 'Missing session token'}), 401
    session = verify_and_load_session(token)
    if session is None:
        return jsonify({'error': 'Invalid or expired session'}), 401
    if not session.is_admin():
        return jsonify({'error': 'Forbidden'}), 403
    return jsonify({'users': ['alice', 'bob', 'charlie']})

@app.route('/api/session/refresh', methods=['POST'])
def refresh_session():
    """Refresh session with updated preferences from request body.
    Accepts JSON with 'preferences' key to merge into session.
    """
    token = request.headers.get('X-Session-Token')
    if not token:
        return jsonify({'error': 'Missing session token'}), 401
    session = verify_and_load_session(token)
    if session is None:
        return jsonify({'error': 'Invalid or expired session'}), 401
    body = request.get_json(silent=True) or {}
    new_prefs = body.get('preferences', {})
    if isinstance(new_prefs, dict):
        session.preferences.update(new_prefs)
    # Re-serialize and re-sign
    raw = pickle.dumps(session)
    encoded = base64.b64encode(raw).decode()
    sig = hmac.new(SECRET_KEY.encode(), raw, hashlib.sha256).hexdigest()
    new_token = f"{encoded}.{sig}"
    return jsonify({'token': new_token, 'status': 'refreshed'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
